/* mng_tables.c - the per-game tables, compiled in.
 *
 * runtime_tables.h is generated by prepare_runtime.py from the verified
 * images and is a property of the player's own game file, so it is compiled
 * into the build rather than shipped in the repository. */
#include "mng_tables.h"

#ifdef MNG_WITH_GAME
#include "runtime_tables.h"
const Module *mng_game_modules(void) { return modules; }
unsigned mng_game_module_count(void)
{
    return (unsigned)(sizeof(modules) / sizeof(modules[0]));
}
#else
const Module *mng_game_modules(void) { return 0; }
unsigned mng_game_module_count(void) { return 0; }
#endif
